inline fun <T> retrying(attempts: Int, body: () -> T): T {
    var last: RuntimeException? = null
    repeat(attempts) {
        try {
            return body()                       // non-local return from retrying
        } catch (e: RuntimeException) {
            last = e
        }
    }
    throw last!!                                // never pass a booking that could happen twice
}
